    lev: { 기본: { q: '‘미지’를 다른 낱말로 바꾸어 뜻이 통하는지 볼 때 바꾸어 넣은 낱말은 무엇일까요?', a: '새로운', steps: ['「국어」 교과서 245쪽 두 친구의 말을 읽는다', '‘미지’ 자리에 넣어 읽은 낱말을 찾는다', '새로운'] }, 도전: { q: '바다와 관련 있는 지도 세 가지는 해저 지도, 해류의 흐름을 나타낸 지도와 무엇일까요?', a: '수온의 분포를 나타낸 지도', steps: ['바다 밑을 지도로 만든 문단을 찾는다', '「…… 등 각종 바다 관련 지도」 앞을 읽는다', '수온의 분포를 나타낸 지도'] }, 심화: { q: '자신이 만들고 싶은 (　　) 지도를 정하고, 만들고 싶은 까닭과 그 지도의 쓰임새를 말해 봐요.', a: '여러 답 (예: 우리 동네 놀이터 지도 — 동생과 놀 곳을 쉽게 찾고 싶어서예요. 이사 온 친구가 동네를 알아 갈 때 쓸 수 있어요.)', open: true } },
